changeSet.sql:
alter table modeling_warehouse_plan_policy
    add constraint ck_warehouse_plan_business_category_mode
    check (business_category_mode in ('SINGLE_DEFAULT','MULTI_SELECT'));
alter table modeling_warehouse_plan_policy
    add constraint ck_warehouse_plan_business_process_mode
    check (business_process_mode in ('AUTO_SELECT_SINGLE','MANAGED'));

rollback.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM modeling_warehouse_plan_policy
         WHERE default_business_category_id IS NOT NULL
            OR business_category_mode <> 'SINGLE_DEFAULT'
            OR business_process_mode <> 'AUTO_SELECT_SINGLE'
    ) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODELING_PLANNING_CONTEXT_POLICY_DATA_EXISTS';
    END IF;
END $$;

changeSet.sql:
alter table sprint64_business_process
    add constraint ck_sprint64_business_process_lifecycle
    check (lifecycle_status in ('ACTIVE','RETIRED'));

rollback.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM sprint64_business_process WHERE lifecycle_status = 'RETIRED') THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_RETIRED_BUSINESS_PROCESS_EXISTS';
    END IF;
END $$;
